def parse_date_flex(s):
    p = s.split('/')
    if len(p) != 3:
        return s
    d, m, y = p[0].strip(), p[1].strip(), p[2].strip()
    if not (d.isdigit() and m.isdigit() and y.isdigit()):
        return s
    return '%04d-%02d-%02d' % (int(y), int(m), int(d))

