def slugify(s):
    t = ''
    for ch in s.lower():
        if (ch.isalnum() and ord(ch) < 128) or ch == '-':
            t += ch
        elif ch.isspace():
            t += '-'
    return '-'.join(p for p in t.split('-') if p)

def parse_flag(s):
    t = str(s).strip().lower()
    if t in ('y', 'yes', '1'):
        return True
    if t in ('n', 'no', '0', 'off', 'false', 'true', 'on'):
        return False
    return None

